static void d3d9_scalar_barrier(void)
{
#ifdef D9WG_RECORDING_WIRE_BARRIERS
    check(SUCCEEDED(CALL(Present)(device,NULL,NULL,NULL,NULL)),"D3D9 scalar wire barrier");
#endif
}
